require_once '../config/database.php';require_once '../config/response.php';require_once '../eventos/helpers.php';$in=readJson();$token=trim($in['token']??'');$status=strtoupper(trim($in['status']??''));if(strlen($token)!==64||!in_array($status,['APROVADO','RECUSADO'],true))jsonResponse(false,'Solicitação inválida.',[],400);$conn->begin_transaction();try{$s=$conn->prepare("SELECT * FROM orcamentos WHERE token_publico=? FOR UPDATE");$s->bind_param('s',$token);$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o)throw new RuntimeException('Orçamento não encontrado.');if(in_array($o['status'],['APROVADO','RECUSADO'],true)){ $conn->commit(); jsonResponse(true,'Resposta já registrada.',['status'=>$o['status']]); }$id=(int)$o['id'];$sid=(int)$o['servico_id'];$up=$conn->prepare('UPDATE orcamentos SET status=?,respondido_em=NOW() WHERE id=?');$up->bind_param('si',$status,$id);$up->execute();$ss=$status==='APROVADO'?'EM_MANUTENCAO':'CANCELADO';$up=$conn->prepare('UPDATE servicos SET status=? WHERE id=?');$up->bind_param('si',$ss,$sid);$up->execute();$h=$conn->prepare("INSERT INTO servicos_historico(servico_id,status_anterior,status_novo,observacao) VALUES(?,'AGUARDANDO_APROVACAO',?,'Resposta pública do orçamento')");$h->bind_param('is',$sid,$ss);$h->execute();criarEventoENotificar($conn,2,0,'Orçamento '.$status,'Cliente respondeu o orçamento.',$status==='APROVADO'?'ATENCAO':'INFORMATIVO','SERVICO',$sid,'ORCAMENTO_RESPOSTA:'.$id.':'.$status,'ORCAMENTOS','ORCAMENTO_'.$status);enfileirarSheets($conn,2,'ORCAMENTO','ORCAMENTO',$id);$conn->commit();jsonResponse(true,'Resposta registrada.',['status'=>$status]);}catch(Throwable $e){$conn->rollback();jsonResponse(false,$e->getMessage(),[],400);}
